mapper.select:
select p.id,p.playlist_name,p.cover_url,p.is_public,p.music_count,p.play_count, p.description,p.user_id,u.username,c.updated_time from playlist as p left join user as u on p.user_id=u.id left join user_collection as c on p.id=c.target_id where c.user_id=#{userId} and c.is_canceled=0
and p.id < #{lastId}
order by c.updated_time desc limit #{pageSize}
